<script lang="ts">
  import type { Contribution } from '#lib/api';
  import { contributionStatus, contributionTitle, matchesContribution, relativeTime, serviceFor, type ContributionFilter } from '#lib/my-page';
  import SiteGlyph from './SiteGlyph.svelte';
  import ContributionBadge from './ContributionBadge.svelte';
  import MyPageIcon from './MyPageIcon.svelte';
  let { items, loading, error, retry, retryIn = 0, onview, filter = $bindable('all') }: { items: Contribution[]; loading: boolean; error: string; retry: () => void; retryIn?: number; onview: (item: Contribution) => void; filter?: ContributionFilter } = $props();
  let query = $state('');
  let currentPage = $state(1);
  const pageSize = 6;
  const filters: { key: ContributionFilter; label: string }[] = [{ key: 'all', label: 'All' }, { key: 'pending', label: 'Pending' }, { key: 'published', label: 'Published' }, { key: 'supported', label: 'Supported' }, { key: 'action', label: 'Needs action' }];
  const filtered = $derived(items.filter(item => matchesContribution(item, filter, query)));
  const pages = $derived(Math.max(1, Math.ceil(filtered.length / pageSize)));
  const activePage = $derived(Math.min(currentPage, pages));
  const visible = $derived(filtered.slice((activePage - 1) * pageSize, activePage * pageSize));
</script>
<section class="contributions-panel" aria-labelledby="contributions-heading" aria-busy={loading}>
  <div class="contributions-heading"><div><h2 id="contributions-heading">My contributions <span>{items.length}</span></h2><p>Follow each workflow from submission to its final result.</p></div><label class="search"><MyPageIcon name="search" size={15}/><input aria-label="Search my contributions" placeholder="Search contributions…" bind:value={query} oninput={() => currentPage = 1}/></label></div>
  <div class="filters" aria-label="Filter contributions">{#each filters as option}<button type="button" aria-pressed={filter === option.key} class:active={filter === option.key} onclick={() => { filter = option.key; currentPage = 1; }}>{option.label}<span>{items.filter(item => matchesContribution(item, option.key, '')).length}</span></button>{/each}</div>
  {#if error}<div class="panel-error" role="alert"><span>{error}</span><button type="button" onclick={retry} disabled={loading || retryIn > 0}>{retryIn > 0 ? `Try again in ${retryIn}s` : 'Try again'}</button></div>{/if}
  {#if loading && !items.length}<div class="loading" role="status">Loading your contributions…<div></div><div></div><div></div></div>
  {:else if visible.length}
    <div class="table-wrap"><table><caption class="sr-only">My contributions and their publication status</caption><thead><tr><th scope="col">Workflow</th><th scope="col">Status</th><th scope="col">Updated</th><th scope="col"><span class="sr-only">Details</span></th></tr></thead><tbody>
    {#each visible as item (item.id)}{@const service = serviceFor(item.url_pattern)}{@const status = contributionStatus(item)}<tr>
      <td><button class="workflow" type="button" onclick={() => onview(item)}><span class="service-icon {service.color}"><SiteGlyph kind={service.glyph}/></span><span class="workflow-copy"><strong>{contributionTitle(item)}</strong><small>{service.name} · {item.reflection?.version_id || item.task_category.replaceAll('-', ' ')}</small></span></button></td>
      <td class="status-cell"><ContributionBadge {item}/><small>{status.key === 'published' ? item.reflection?.kind === 'updated' ? 'Improved version' : 'Available to other agents' : status.key === 'supported' ? 'Existing memory strengthened' : status.action ? 'Your input is needed' : status.key === 'retry_scheduled' ? 'We will try again' : status.key === 'unknown' ? 'Publication not yet linked' : ''}</small></td>
      <td class="updated"><span>{item.progress?.updated_at !== undefined ? relativeTime(item.progress.updated_at) : 'Submitted ' + relativeTime(item.submitted_at)}</span></td>
      <td class="row-action"><button type="button" class="detail-button" aria-label={'View contribution ' + item.id} onclick={() => onview(item)}><MyPageIcon name="chevron" size={16}/></button></td>
    </tr>{/each}
    </tbody></table></div>
    <div class="pagination"><span>Showing {(activePage - 1) * pageSize + 1}–{Math.min(activePage * pageSize, filtered.length)} of {filtered.length}</span><div><button type="button" aria-label="Previous contributions page" disabled={activePage === 1} onclick={() => currentPage = activePage - 1}>Previous</button><span>{activePage} / {pages}</span><button type="button" aria-label="Next contributions page" disabled={activePage === pages} onclick={() => currentPage = activePage + 1}>Next</button></div></div>
  {:else if !error}<div class="empty"><span class="empty-icon"><MyPageIcon name="memory" size={28}/></span><h3>{items.length ? 'No matching contributions.' : 'Your first contribution starts here.'}</h3><p>{items.length ? 'Try another search or status filter.' : 'Share a useful workflow and follow its progress here.'}</p>{#if items.length}<button type="button" class="clear-filter" onclick={() => { query = ''; filter = 'all'; }}>Clear filters</button>{:else}<a href="/contribute" class="button button-dark button-small">Share a workflow <span aria-hidden="true">↗</span></a>{/if}</div>{/if}
</section>
<style>
.contributions-panel{min-width:0;border:1px solid var(--line);border-radius:12px;background:var(--paper);overflow:hidden}.contributions-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:22px 24px 17px;margin-bottom:0}h2{display:flex;gap:9px;align-items:center;margin:0 0 7px;font:650 19px/1.3 Manrope,sans-serif;letter-spacing:-.04em}h2 span{padding:2px 6px;border-radius:4px;background:#f0f3ea;color:#52634f;font:500 10px 'DM Mono',monospace}.contributions-heading p{margin:0;color:#52634f;font-size:11px;line-height:1.6}.search{display:flex;align-items:center;gap:7px;max-width:220px;padding:8px 10px;border:1px solid #e0e5da;border-radius:7px;color:#718074;background:#fafbf6}.search input{min-width:0;width:100%;border:0;background:transparent;color:#244337;outline-offset:7px;font-size:11px}.filters{display:flex;flex-wrap:wrap;gap:6px;padding:0 24px 20px}.filters button{display:flex;align-items:center;gap:7px;min-height:32px;padding:6px 9px;border:1px solid #e6e9df;border-radius:6px;background:#fffefa;color:#52634f;font-size:11px;font-weight:600;cursor:pointer}.filters button.active{background:#193d30;border-color:#193d30;color:#fffef4}.filters button span{font-family:'DM Mono',monospace;font-size:10px;opacity:1}.table-wrap{padding:0 18px}table{width:100%;border-collapse:collapse;text-align:left}th{padding:10px 7px;background:#f7f8f1;color:#52634f;font:500 9px 'DM Mono',monospace;letter-spacing:.05em;text-transform:uppercase}th:first-child{border-radius:5px 0 0 5px}th:last-child{border-radius:0 5px 5px 0}td{padding:16px 7px;border-bottom:1px solid #edf0e6;vertical-align:middle}.workflow{display:flex;align-items:center;gap:11px;min-width:0;padding:0;border:0;background:none;text-align:left;color:inherit;cursor:pointer}.service-icon{display:grid;place-items:center;flex:none;width:34px;height:36px;border-radius:7px;background:#edf1e9;color:#527158}.service-icon :global(svg){width:22px;height:22px}.docs{color:#477ba5;background:#edf3f8}.sheets{color:#3a7d53;background:#edf5e9}.notion{color:#58615c;background:#f0f0eb}.calendar{color:#467da0;background:#edf4f7}.mail{color:#a36750;background:#faf0e8}.workflow-copy{display:grid;gap:5px;min-width:0}.workflow strong{font-size:13px;font-weight:650;line-height:1.5;max-width:320px;overflow-wrap:anywhere}.workflow small,.status-cell small{display:block;color:#52634f;font-size:10px;line-height:1.5}.status-cell{min-width:125px}.status-cell small{margin-top:5px;font-size:11px}.updated{color:#52634f;font-size:10px;white-space:nowrap}.detail-button{display:grid;place-items:center;width:30px;height:32px;padding:0;border:0;border-radius:6px;background:none;color:#6d7a70;cursor:pointer}.detail-button:hover{background:#eef2e8;color:#1c4b37}.pagination{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:15px 24px;color:#52634f;font-size:10px}.pagination>div{display:flex;gap:9px;align-items:center}.pagination button{padding:6px 9px;border:1px solid #e4e8dd;border-radius:5px;background:#fffefa;color:#4e6556;font-size:10px;cursor:pointer}.pagination button:disabled{opacity:.4;cursor:default}.panel-error{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:0 24px 16px;padding:12px;border:1px solid #ebd7c9;border-radius:7px;background:#fbf2e9;color:#8b5940;font-size:11px}.panel-error button,.clear-filter{border:0;background:none;color:#335c42;text-decoration:underline;font:inherit;cursor:pointer}.empty{text-align:center;padding:56px 24px}.empty-icon{display:inline-grid;place-items:center;width:54px;height:54px;margin-bottom:16px;border-radius:14px;background:#edf3e6;color:#66805d}.empty h3{margin:0 0 8px;font:600 20px Manrope,sans-serif;letter-spacing:-.035em}.empty p{font-size:12px;color:#52634f;line-height:1.7}.loading{padding:24px;color:#687667;font-size:12px}.loading div{height:40px;margin-top:15px;border-radius:6px;background:#f1f4ea}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}
@media(max-width:1050px){.contributions-heading{align-items:flex-start;flex-direction:column}.search{max-width:none;width:100%}.workflow strong{max-width:250px}}
@media(max-width:650px){.contributions-heading{padding:19px 18px 15px}.filters{padding:0 18px 15px;gap:5px}.filters button{padding:6px 7px}.table-wrap{padding:0 14px}thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}tbody,tr{display:block}tr{position:relative;padding:16px 0 14px;border-bottom:1px solid #e8ece0}td{display:block;padding:0;border:0}.workflow{gap:10px;padding-right:45px}.workflow strong{max-width:none;font-size:12px}.workflow small{font-size:10px}.status-cell{padding-left:44px;margin-top:10px}.status-cell small{max-width:190px;font-size:10px}.updated{position:absolute;right:0;top:19px;bottom:auto;font-size:10px}.row-action{position:absolute;right:0;top:auto;bottom:14px}.pagination{padding:15px 18px;flex-wrap:wrap}.pagination>div{margin-left:auto}.empty{padding:42px 18px}}
</style>
